			dc.l kw_inc, var_nobump_v
			dc.l p_nobump_r

; ============================================================
; function fact (turbo mode)
; ============================================================

p_fact:

			; main.bas 191: Dim r As Integer

			; main.bas 192: r = 1
			dc.l kw_ltov, 1, var_fact_r

			; main.bas 193: Do While k > 1
do9_t:
			dc.l kw_scpgtvl, var_fact_k, 1
			dc.l kw_goto_iffalse, do9_e

			; main.bas 194: r = r * k
			dc.l kw_mulvv, var_fact_r, var_fact_k, var_fact_r

			; main.bas 195: k = k - 1
			dc.l kw_dec, var_fact_k

			; main.bas 196: Loop
			dc.l do9_t_go
do9_e:

			; main.bas 197: Fact = r
			dc.l kw_vtov, var_fact_r, var_fact_fact
			dc.l p_fact_r

; ============================================================
; function counter (turbo mode)
; ============================================================

p_counter:

			; main.bas 201: Static calls As Integer

			; main.bas 202: calls = calls + 1
			dc.l kw_inc, var_counter_calls

			; main.bas 203: Counter = calls
			dc.l kw_vtov, var_counter_calls, var_counter_counter
			dc.l p_counter_r

; ============================================================
; function fresh (turbo mode)
; ============================================================

p_fresh:

			; main.bas 207: Dim calls As Integer

			; main.bas 208: calls = calls + 1
			dc.l kw_inc, var_fresh_calls

			; main.bas 209: Fresh = calls
			dc.l kw_vtov, var_fresh_calls, var_fresh_fresh
			dc.l p_fresh_r

; ============================================================
; function clamp (turbo mode)
; ============================================================

p_clamp:

			; main.bas 213: Clamp = v
			dc.l kw_vtov, var_clamp_v, var_clamp_clamp

			; main.bas 214: If v > MAXN Then
			dc.l kw_scpgtvl, var_clamp_v, 10
			dc.l kw_goto_iffalse, if10_1

			; main.bas 215: Clamp = MAXN
			dc.l kw_ltov, 10, var_clamp_clamp

			; main.bas 216: Exit Function
			dc.l p_clamp_r

			; main.bas 217: End If
if10_1:

			; main.bas 218: If v < 0 Then Clamp = 0
			dc.l kw_scpltvl, var_clamp_v, 0
			dc.l kw_goto_iffalse, if11_1
			dc.l kw_ztov, var_clamp_clamp
if11_1:
			dc.l p_clamp_r

; ============================================================
; function grade (turbo mode)
; ============================================================

p_grade:

			; main.bas 222: Select Case score
			dc.l kw_vtov, var_grade_score, var_grade___sel12

			; main.bas 223: Case Is >= 90
			dc.l kw_scpgevl, var_grade___sel12, 90
			dc.l kw_goto_iffalse, sel12_1
sel12_b1:

			; main.bas 224: Grade = 1
			dc.l kw_ltov, 1, var_grade_grade

			; main.bas 225: Case 80 To 89
			dc.l sel12_e_go
sel12_1:
			dc.l kw_scpltvl, var_grade___sel12, 80
			dc.l kw_goto_iftrue, sel12_2
			dc.l kw_scplevl, var_grade___sel12, 89
			dc.l kw_goto_iffalse, sel12_2
sel12_b2:

			; main.bas 226: Grade = 2
			dc.l kw_ltov, 2, var_grade_grade

			; main.bas 227: Case 60, 65, 70, 75
			dc.l sel12_e_go
sel12_2:
			dc.l kw_cpeqvl, var_grade___sel12, 60
			dc.l kw_goto_iftrue, sel12_b3
			dc.l kw_cpeqvl, var_grade___sel12, 65
			dc.l kw_goto_iftrue, sel12_b3
			dc.l kw_cpeqvl, var_grade___sel12, 70
			dc.l kw_goto_iftrue, sel12_b3
			dc.l kw_cpeqvl, var_grade___sel12, 75
			dc.l kw_goto_iffalse, sel12_3
sel12_b3:

			; main.bas 228: Grade = 3
			dc.l kw_ltov, 3, var_grade_grade

			; main.bas 229: Case Else
			dc.l sel12_e_go
sel12_3:

			; main.bas 230: Grade = 4
			dc.l kw_ltov, 4, var_grade_grade

			; main.bas 231: End Select
sel12_e:
			dc.l p_grade_r

