p_kind:

			; main.bas 235: Select Case f
			dc.l kw_strcpy, var_kind___sel13, var_kind_f

			; main.bas 236: Case "apple", "banana"
			dc.l kw_strcmpeq, var_kind___sel13, str4
			dc.l kw_goto_iftrue, sel13_b1
			dc.l kw_strcmpeq, var_kind___sel13, str58
			dc.l kw_goto_iffalse, sel13_1
sel13_b1:

			; main.bas 237: Kind = 1
			dc.l kw_ltov, 1, var_kind_kind

			; main.bas 238: Case "pear"
			dc.l sel13_e_go
sel13_1:
			dc.l kw_strcmpeq, var_kind___sel13, str5
			dc.l kw_goto_iffalse, sel13_2
sel13_b2:

			; main.bas 239: Kind = 2
			dc.l kw_ltov, 2, var_kind_kind

			; main.bas 240: End Select
sel13_2:
sel13_e:
			dc.l p_kind_r

