;   p_name_c: call a procedure, p_name_r: end of it
;   turbo mode ends with ret, normal mode with jp ntc_xn
; ============================================================

if7_e_go:			lea if7_e, sp
			rts
if8_e_go:			lea if8_e, sp
			rts
do9_t_go:			lea do9_t, sp
			rts
sel12_e_go:			lea sel12_e, sp
			rts
sel13_e_go:			lea sel13_e, sp
			rts

p_chk_c:		; call chk
			movea.l (sp)+, a0		; got
			move.w (a0), var_chk_got
			movea.l (sp)+, a0		; want
			move.w (a0), var_chk_want
			move.l sp, p_chk_rs
			lea p_chk, sp
			rts
p_chk_r:		; end of chk
			movea.l p_chk_rs, sp
			rts
p_chks_c:		; call chks
			movea.l (sp)+, a0		; got
			lea var_chks_got, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si0_e
p_chks_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si0
			beq p_chks_si0_z
p_chks_si0_e:
			clr.b (a1)
p_chks_si0_z:
			movea.l (sp)+, a0		; want
			lea var_chks_want, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_chks_si1_e
p_chks_si1:
			move.b (a0)+, (a1)+
			dbeq d1, p_chks_si1
			beq p_chks_si1_z
p_chks_si1_e:
			clr.b (a1)
p_chks_si1_z:
			move.l sp, p_chks_rs
			lea p_chks, sp
			rts
p_chks_r:		; end of chks
			movea.l p_chks_rs, sp
			rts
p_add_c:		; call add
			movea.l (sp)+, a0		; x
			move.w (a0), var_add_x
			movea.l (sp)+, a0		; y
			move.w (a0), var_add_y
			clr.w var_add_add
			move.l sp, p_add_rs
			lea p_add, sp
			rts
p_add_r:		; end of add
			movea.l p_add_rs, sp
			rts
p_twice_c:		; call twice
			movea.l (sp)+, a0		; v
			move.w (a0), var_twice_v
			clr.w var_twice_twice
			move.l sp, p_twice_rs
			lea p_twice, sp
			rts
p_twice_r:		; end of twice
			movea.l p_twice_rs, sp
			rts
p_bump_c:		; call bump
			movea.l (sp)+, a0		; v
			move.l a0, p_bump_a0
			move.w (a0), var_bump_v
			move.l sp, p_bump_rs
			lea p_bump, sp
			rts
p_bump_r:		; end of bump
			movea.l p_bump_a0, a1
			move.w var_bump_v, (a1)
			movea.l p_bump_rs, sp
			rts
p_nobump_c:		; call nobump
			movea.l (sp)+, a0		; v
			move.w (a0), var_nobump_v
			move.l sp, p_nobump_rs
			lea p_nobump, sp
			rts
p_nobump_r:		; end of nobump
			movea.l p_nobump_rs, sp
			rts
p_fact_c:		; call fact
			movea.l (sp)+, a0		; k
			move.w (a0), var_fact_k
			clr.w var_fact_fact
			clr.w var_fact_r
			move.l sp, p_fact_rs
			lea p_fact, sp
			rts
p_fact_r:		; end of fact
			movea.l p_fact_rs, sp
			rts
p_counter_c:		; call counter
			clr.w var_counter_counter
			move.l sp, p_counter_rs
			lea p_counter, sp
			rts
p_counter_r:		; end of counter
			movea.l p_counter_rs, sp
			rts
p_fresh_c:		; call fresh
			clr.w var_fresh_fresh
			clr.w var_fresh_calls
			move.l sp, p_fresh_rs
			lea p_fresh, sp
			rts
p_fresh_r:		; end of fresh
			movea.l p_fresh_rs, sp
			rts
p_clamp_c:		; call clamp
			movea.l (sp)+, a0		; v
			move.w (a0), var_clamp_v
			clr.w var_clamp_clamp
			move.l sp, p_clamp_rs
			lea p_clamp, sp
			rts
p_clamp_r:		; end of clamp
			movea.l p_clamp_rs, sp
			rts
p_grade_c:		; call grade
			movea.l (sp)+, a0		; score
			move.w (a0), var_grade_score
			clr.w var_grade_grade
			move.l sp, p_grade_rs
			lea p_grade, sp
			rts
p_grade_r:		; end of grade
			movea.l p_grade_rs, sp
			rts
p_kind_c:		; call kind
			movea.l (sp)+, a0		; f
			lea var_kind_f, a1
			move.w #40, d1
			subq.w #1, d1
			bmi p_kind_si0_e
p_kind_si0:
			move.b (a0)+, (a1)+
			dbeq d1, p_kind_si0
			beq p_kind_si0_z
p_kind_si0_e:
			clr.b (a1)
p_kind_si0_z:
			clr.w var_kind_kind
			move.l sp, p_kind_rs
			lea p_kind, sp
			rts
p_kind_r:		; end of kind
			movea.l p_kind_rs, sp
			rts
p_sum3_c:		; call sum3
			movea.l (sp)+, a0		; x
			move.w (a0), var_sum3_x
			movea.l (sp)+, a0		; y
			move.w (a0), var_sum3_y
			movea.l (sp)+, a0		; z
			move.w (a0), var_sum3_z
